use customer_behaviour;
rename table customer to customers;
select * from customers
limit 10;

-- 01. What is the total revenue generated by male vs female customers? 
select gender,  sum(purchase_amount) as total_revenue
from customers
group by gender;

-- 02. Which customers used a discount but still they spent more than the average purchase amount?
 select customer_id , purchase_amount
 from customers
 where discount_applied = 'yes' and purchase_amount >= (select avg(purchase_amount)from customers);
 
 -- 03. Which are the top 5 products with the highest average review rating?
 select item_purchased, round(avg(review_rating),2) as `average product rating`
 from customers
 group by item_purchased
 order by `average product rating` desc
 limit 5;
 
 -- 04. Compare the average purchase amount between standart and express?
 select shipping_type, round(avg(purchase_amount),2) as `shipping type`
 from customers
 where shipping_type in ('Standard','express')
 group by shipping_type;
 
 
-- 05. Do subscribed customers spend more? compare average spend and total revenue between
--     subscribers customer or non subscribers customer;
select subscription_status,
count(customer_id) as `total customer`,
round(avg(purchase_amount),2) as `total average`,
sum(purchase_amount) as `total revenue`
from customers
group by subscription_status
order by `total average`,`total revenue` desc;

-- 06. Which products have the highest percentage of purchases with the discounts applied ?

select item_purchased,
round(100 * sum(case when discount_applied = 'yes' then 1 else 0 end) / count(*),2) as discount_rate
from customers
group by item_purchased 
order by discount_rate desc
limit 5;

-- 07. Segment customers into new, returning, and loyal based on their numbers of previous purchases
-- and show the count of each segment;

with customer_type as (
select customer_id, previous_purchases,
case
   when previous_purchases = 1 then 'new'
   when previous_purchases between 2 and 10 then 'returning'
   else 'loyal'
   end as customer_segment
from customers
)
select customer_segment, count(*) as `numbers of customers`
from customer_type
group by customer_segment;


-- 08. What are the top 3 most purchased product within each category?

with item_count as (
select category, item_purchased,
count(customer_id) as total_orders,
row_number() over(partition by category order by count(customer_id) desc) as item_rank
from customers
group by category, item_purchased
)

select item_rank, category, item_purchased, total_orders
from item_count
where item_rank <= 3;

-- 09. Are customers who are repeat buyers (more than 5 previous purchase) also likely to subscribe?

select subscription_status,
count(customer_id) as repeat_buyers
from customers
where previous_purchases > 5
group by subscription_status;


-- 10. what is the revenue contribution of each age group;

select age_group,
sum(purchase_amount) as total_revenue
from customers
group by age_group
order by total_revenue desc;




 
 

 
 
 
 
 
 
 